with Base as (select *, unit_price * quantity as line_total from order_items where product_id is null and product_id = 19), order_items_stats as (select case when quantity >= 9 then 'high' when quantity >= 3 then 'mid' else 'low' end as quantity_bucket, max(line_total) - min(line_total) as line_total_range, max(unit_price) as max_unit_price from Base group by case when quantity >= 9 then 'high' when quantity >= 3 then 'mid' else 'low' end) select quantity_bucket, line_total_range, max_unit_price from order_items_stats order by 2, quantity_bucket limit 10
